// QA Gate (Drawing Edition) — ตรวจโครงชุดใบงานแบบภาพวาดก่อนเสียเงินเจนภาพ
// ไม่ผ่าน -> ส่ง qa_notes กลับ Agent 3 แก้ 1 รอบ แล้ว force-pass กัน pipeline ค้าง
const MAX_RETRIES = 1;
const attempt = (typeof $runIndex !== 'undefined' && $runIndex != null) ? $runIndex : 0;

let data = null;
try { data = $('3. Content Creation Agent').last().json.output; } catch (e) {}

const problems = [];
const FULL = ['color_by_number_scene', 'color_mixing_scene', 'board_game', 'coloring_scene'];
const GRID = ['picture_grid', 'count_and_write'];
const KEYED = ['color_by_number_scene', 'color_mixing_scene'];
const BASE_COLORS = ['red', 'blue', 'yellow', 'white', 'black'];

if (!data || !data.title || !Array.isArray(data.pages) || data.pages.length === 0) {
  problems.push('No valid title/pages returned — regenerate the full worksheet JSON.');
} else {
  const pages = data.pages;
  if (pages.length < 5 || pages.length > 7) problems.push('Pack has ' + pages.length + ' pages; make 5-7 pages total (4-6 activity pages + the final answer_key).');
  const lastType = String((pages[pages.length - 1] || {}).activity_type || '').toLowerCase();
  if (lastType !== 'answer_key') problems.push('The LAST page must be activity_type "answer_key".');
  if (!data.mascot_prompt) problems.push('mascot_prompt is missing.');
  if (!data.cover_hint) problems.push('cover_hint is missing.');

  let imageJobs = 2; // cover + mascot
  pages.forEach((p, idx) => {
    const t = String(p.activity_type || '').toLowerCase();
    const items = Array.isArray(p.items) ? p.items : [];
    const label = 'Page ' + (idx + 1) + ' ("' + (p.page_title || '') + '", ' + t + ')';

    if (t === 'answer_key') {
      if (items.length === 0) problems.push(label + ' must list the answers for every page.');
      return;
    }
    if (!FULL.includes(t) && !GRID.includes(t)) problems.push(label + ': unknown activity_type — use only color_by_number_scene, color_mixing_scene, picture_grid, board_game, coloring_scene, count_and_write, answer_key.');
    if (!p.scene_prompt || String(p.scene_prompt).length < 40) problems.push(label + ': scene_prompt is missing or too short — write a detailed English image prompt (2-3 sentences).');
    imageJobs += 1;

    if (/\b(colorful|vibrant|red|blue|green|yellow|orange|purple|pink)\b/i.test(String(p.scene_prompt || '')) && !KEYED.includes(t)) {
      problems.push(label + ': scene_prompt mentions colors — inside pages must be pure black-and-white line art, remove color words.');
    }
    if (t === 'color_by_number_scene') {
      const key = Array.isArray(p.color_key) ? p.color_key : [];
      if (key.length < 5 || key.length > 8) problems.push(label + ': color_key must have 5-8 entries of {answer, color}.');
    }
    if (t === 'color_mixing_scene') {
      const key = Array.isArray(p.color_key) ? p.color_key : [];
      const mixes = Array.isArray(p.mix_key) ? p.mix_key : [];
      if (key.length < 2 || key.length > 4) problems.push(label + ': color_key (base paint colors) must have 2-4 entries.');
      key.forEach(k => {
        if (!BASE_COLORS.includes(String(k.color || '').toLowerCase().trim())) problems.push(label + ': base color "' + k.color + '" not allowed — use only red, blue, yellow, white, black.');
      });
      if (mixes.length < 4 || mixes.length > 8) problems.push(label + ': mix_key must have 4-8 entries of {fact, mix, result}.');
      mixes.forEach(m => {
        if (!m || !m.fact || !m.mix || !m.result) problems.push(label + ': every mix_key entry needs fact, mix and result.');
      });
    }
    if (GRID.includes(t)) {
      if (items.length < 4 || items.length > 8) problems.push(label + ': grid pages need 4-8 numbered items (one per panel in the picture).');
    }
    items.forEach(it => { if (String(it).length > 90) problems.push(label + ': an item is ' + String(it).length + ' chars — keep every item under 90 chars.'); });
  });

  if (imageJobs < 5 || imageJobs > 8) problems.push('Total images would be ' + imageJobs + ' (cover + mascot + 1 per activity page). Adjust page count so the total is 5-8 (i.e. 3-6 activity pages).');
}

let pass = problems.length === 0;
let forced = false;
if (!pass && attempt >= MAX_RETRIES) { pass = true; forced = true; }

return [{ json: {
  qa_pass: pass,
  qa_forced: forced,
  qa_attempt: attempt,
  qa_notes: problems.length ? ('- ' + problems.join('\n- ')) : ''
} }];

const data = $('3. Content Creation Agent').last().json.output;
if (!data || !data.title || !Array.isArray(data.pages) || data.pages.length === 0) {
  throw new Error('Content Agent ไม่ได้ส่ง title/pages ที่ถูกต้อง ข้อมูลที่ได้: ' + JSON.stringify($json).slice(0, 300));
}

// สไตล์บังคับสำหรับภาพหน้าใน (ขาวดำล้วน) — เติมท้ายทุก prompt อัตโนมัติ
const BW_STYLE = '. Black and white line art ONLY, thick bold clean outlines, cute kawaii cartoon style for kids, pure white background, no shading, no gray tones, absolutely no color. The artwork should fill most of the canvas, but keep every important element fully inside the frame with a small safe margin from all four edges — nothing may be cut off at the canvas borders.';
const GRID = ['picture_grid', 'count_and_write'];

const jobs = [];

// 1 รูปสี: หน้าปก
jobs.push({
  job_id: 'cover',
  prompt: 'Colorful cover art for a children\'s educational worksheet pack titled "' + data.title + '". ' + (data.cover_hint || '') + ' Cute flat vector clipart style for teachers, bright cheerful colors, clean uncluttered composition, artwork filling the whole canvas, and large clear bold title text near the top that reads exactly: ' + data.title + '. Keep the title text and main characters comfortably away from the outer edges of the image.',
  size: '1024x1536',
  quality: 'medium'
});

// mascot ขาวดำ ติดมุมทุกหน้า
jobs.push({
  job_id: 'mascot',
  prompt: 'A single cute cartoon mascot for a kids worksheet, one simple character centered, no text or letters anywhere' + BW_STYLE + ' The mascot is: ' + (data.mascot_prompt || 'a happy pencil holding a book'),
  size: '1024x1024',
  quality: 'low'
});

// 1 รูปขาวดำต่อหน้ากิจกรรม — สัดส่วนภาพจับคู่กับพื้นที่จริงบนหน้ากระดาษ:
// เต็มหน้า = จัตุรัส 1024x1024 (พื้นที่หลังหักหัวกระดาษ ~7.3x7.5in), ตาราง = แนวนอน 1536x1024 (เหลือที่ให้โจทย์ใต้ภาพ)
data.pages.forEach((p, idx) => {
  const t = String(p.activity_type || '').toLowerCase();
  if (t === 'answer_key' || !p.scene_prompt) return;
  jobs.push({
    job_id: 'page_' + idx,
    prompt: String(p.scene_prompt) + BW_STYLE,
    size: GRID.includes(t) ? '1536x1024' : '1024x1024',
    quality: 'medium'
  });
});

return jobs.map(j => ({ json: j }));

// จับคู่ผลลัพธ์ภาพกลับเข้า job_id (ลำดับ item ตรงกับ Extract Image Jobs เพราะ HTTP node รันทีละ item)
const jobs = $('Extract Image Jobs').all().map(i => i.json);
const responses = $input.all().map(i => i.json);

const images = {};
jobs.forEach((job, i) => {
  const r = responses[i] || {};
  images[job.job_id] = (r.data && r.data[0] && r.data[0].b64_json) || '';
});

const ok = Object.values(images).filter(Boolean).length;
return [{ json: { images: images, attempt: 0, images_ok: ok, images_total: jobs.length } }];

// Image QA — ตรวจว่าภาพเจนครบทุก job ไหม ถ้าขาดส่งเฉพาะรูปที่ขาดไปยิงซ้ำ (สูงสุด 2 รอบ)
const MAX_IMG_RETRIES = 2;
const jobs = $('Extract Image Jobs').all().map(i => i.json);
const images = $json.images || {};
const attempt = Number.isInteger($json.attempt) ? $json.attempt : 0;

const missing = jobs.filter(j => !images[j.job_id]);

if (missing.length === 0 || attempt >= MAX_IMG_RETRIES) {
  return [{ json: {
    images: images,
    qa_images_done: true,
    attempt: attempt,
    missing_ids: missing.map(j => j.job_id)
  } }];
}

// ส่ง 1 item ต่อรูปที่ขาด (แนบ images map ไว้กับ item แรกเพื่อส่งต่อให้ Merge)
return missing.map((j, idx) => ({ json: {
  ...j,
  qa_images_done: false,
  attempt: attempt + 1,
  images: idx === 0 ? images : undefined
} }));

// รวมภาพที่ยิงซ้ำสำเร็จกลับเข้า images map แล้ววนกลับไปตรวจอีกรอบ
const retriedJobs = $('Image QA').all().map(i => i.json);
const responses = $input.all().map(i => i.json);

const images = { ...((retriedJobs[0] && retriedJobs[0].images) || {}) };
retriedJobs.forEach((job, i) => {
  const r = responses[i] || {};
  const b64 = (r.data && r.data[0] && r.data[0].b64_json) || '';
  if (b64) images[job.job_id] = b64;
});

const attempt = (retriedJobs[0] && retriedJobs[0].attempt) || 1;
return [{ json: { images: images, attempt: attempt } }];

const data = $('3. Content Creation Agent').last().json.output;
// map ภาพสุดท้าย (หลัง Image QA retry) — fallback ไป Collect Images ถ้าไม่มี
let images = {};
if ($json.images && typeof $json.images === 'object') images = $json.images;
if (!Object.keys(images).length) { try { images = $('Image QA').first().json.images || {}; } catch (e) {} }
if (!Object.keys(images).length) { try { images = $('Collect Images').first().json.images || {}; } catch (e) {} }

if (!data || !data.title || !Array.isArray(data.pages) || data.pages.length === 0) {
  throw new Error('Content Agent ไม่ได้ส่ง title/pages ที่ถูกต้อง');
}

const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const blankify = s => esc(s).replace(/_{3,}/g, `<span class='blank'></span>`);

const CSS_COLORS = { red: '#e53935', blue: '#1e88e5', green: '#43a047', yellow: '#fdd835', orange: '#fb8c00', purple: '#8e24aa', pink: '#f48fb1', brown: '#6d4c41', black: '#212121', gray: '#9e9e9e', grey: '#9e9e9e', white: '#ffffff', lightblue: '#81d4fa', 'light blue': '#81d4fa', lightgreen: '#aed581', 'light green': '#aed581', darkred: '#8e2424', 'dark red': '#8e2424', 'dark blue': '#1a3e8c', darkblue: '#1a3e8c' };
const swatch = c => CSS_COLORS[String(c || '').toLowerCase().trim()] || '#cccccc';

const img = (id, cls) => images[id]
  ? `<img class='${cls}' src='data:image/jpeg;base64,${images[id]}'/>`
  : `<div class='img-missing'>(image was not generated)</div>`;

const mascotImg = images.mascot ? `<img class='mascot' src='data:image/jpeg;base64,${images.mascot}'/>` : '';
const coverHtml = images.cover ? `<div class='page cover'><img class='cover-img' src='data:image/jpeg;base64,${images.cover}'/></div>` : '';

const colorKeyHtml = key => `<div class='key'>` + key.map(k =>
  `<div class='key-cell'><div class='key-num'>${esc(k.answer)}</div><div class='key-swatch' style='background:${swatch(k.color)}'></div><div class='key-name'>${esc(k.color)}</div></div>`
).join('') + `</div>`;

// ตัวอย่างผสมสี 1 ข้อ (จาก mix_key ข้อแรก) — โชว์วิธีคิด ไม่เฉลยข้ออื่น
const sw = c => `<span class='mix-sw' style='background:${swatch(c)}'></span>`;
const mixDemoHtml = m => {
  const parts = String(m.mix || '').split('+').map(s => s.trim());
  return `<div class='mix-demo'>Example: <b>${esc(m.fact)}</b> = ` +
    `${sw(parts[0])} ${esc(parts[0] || '')} + ${sw(parts[1])} ${esc(parts[1] || '')}` +
    ` → ${sw(m.result)} <b>${esc(m.result)}</b>!</div>`;
};

const GRID = ['picture_grid', 'count_and_write'];
const KEYED = ['color_by_number_scene', 'color_mixing_scene'];

const pagesHtml = coverHtml + data.pages.map((p, i) => {
  const t = String(p.activity_type || '').toLowerCase();
  const items = Array.isArray(p.items) ? p.items : [];
  const hasKey = KEYED.includes(t) && Array.isArray(p.color_key) && p.color_key.length > 0;
  const hasMixDemo = t === 'color_mixing_scene' && Array.isArray(p.mix_key) && p.mix_key.length > 0;

  let body = '';
  if (t === 'answer_key') {
    body = items.map(w => `<div class='info-box'>${blankify(w)}</div>`).join('');
  } else if (GRID.includes(t)) {
    // ตัดเลขข้อที่โมเดลใส่มาเองออกก่อน (กัน "1. 1. ..." ซ้ำ)
    const clean = w => String(w).replace(/^\s*\d+\s*[\.\)]\s*/, '');
    body = `<div class='scene-wrap'>${img('page_' + i, 'scene-grid')}</div>` +
      `<div class='q-list'>` + items.map((w, qi) => `<div class='q-row'>${qi + 1}. ${blankify(clean(w))}</div>`).join('') + `</div>`;
  } else {
    const cls = hasMixDemo ? 'scene-full with-mix' : (hasKey ? 'scene-full with-key' : 'scene-full');
    body = `<div class='scene-wrap fill'>${img('page_' + i, cls)}</div>`;
  }

  return `
<div class='page'>
  <div class='frame'></div>
  <div class='meta-row'><span>Name: ____________________</span><span>Date: __________</span></div>
  <div class='head-row'><h2 class='page-title'>${esc(p.page_title || 'Page ' + (i + 1))}</h2>${mascotImg}</div>
  ${p.instructions ? `<p class='inst'>✏️ ${esc(p.instructions)}</p>` : ''}
  ${hasKey ? colorKeyHtml(p.color_key) : ''}
  ${hasMixDemo ? mixDemoHtml(p.mix_key[0]) : ''}
  <div class='body'>${body}</div>
  <div class='foot'><div class='footer'>${esc(data.title)} • Page ${i + 1} of ${data.pages.length}</div></div>
</div>`;
}).join('');

const html = `<!DOCTYPE html>
<html>
<head>
<meta charset='utf-8'>
<link href='https://fonts.googleapis.com/css2?family=Baloo+2:wght@500;800&family=Schoolbell&display=swap' rel='stylesheet'>
<style>
  @page { size: Letter; margin: 0; }
  body { margin: 0; font-family: 'Baloo 2', Arial, sans-serif; color: #222; }
  .page { width: 8.5in; height: 10.95in; box-sizing: border-box; padding: 0.45in 0.6in 0.85in 0.6in; page-break-after: always; page-break-inside: avoid; position: relative; display: flex; flex-direction: column; overflow: hidden; }
  .frame { position: absolute; top: 0.22in; left: 0.22in; right: 0.22in; bottom: 0.22in; border: 2px dashed #c9d6f0; border-radius: 16px; pointer-events: none; }
  .meta-row { display: flex; justify-content: space-between; margin: 4px 2px 2px; font-size: 14px; }
  .head-row { display: flex; align-items: center; gap: 12px; justify-content: center; }
  .page-title { text-align: center; font-size: 28px; margin: 6px 0 2px; flex: 1; }
  .mascot { flex: none; width: 0.85in; height: 0.85in; object-fit: contain; }
  .inst { background: #f7f7f7; border: 2px dashed #999; border-radius: 10px; padding: 7px 12px; font-size: 15px; margin: 6px 0; }
  .key { display: flex; gap: 6px; justify-content: center; margin: 5px 0; flex-wrap: nowrap; }
  .key-cell { border: 2px solid #333; border-radius: 8px; padding: 3px 6px 4px; text-align: center; min-width: 0.58in; }
  .key-num { font-weight: 800; font-size: 15px; line-height: 1.1; }
  .key-swatch { height: 10px; border-radius: 5px; margin: 2px 0; border: 1px solid #999; }
  .key-name { font-size: 9px; }
  .body { flex: 1 1 auto; display: flex; flex-direction: column; }
  .scene-wrap { text-align: center; }
  .scene-wrap.fill { flex: 1 1 auto; display: flex; align-items: center; justify-content: center; }
  .scene-full, .scene-grid { border: 3.5px solid #2b2b2b; border-radius: 14px; background: #fff; padding: 6px; box-sizing: border-box; }
  .scene-full { width: 100%; max-height: 7.2in; object-fit: contain; }
  .scene-full.with-key { max-height: 6.4in; }
  .scene-full.with-mix { max-height: 6.0in; }
  .mix-demo { text-align: center; font-size: 14px; background: #fffbe8; border: 2px dashed #d8b64a; border-radius: 10px; padding: 5px 10px; margin: 4px auto 2px; width: fit-content; }
  .mix-sw { display: inline-block; width: 16px; height: 16px; border-radius: 4px; border: 1.5px solid #888; vertical-align: -3px; }
  .scene-grid { width: 100%; max-height: 5.0in; object-fit: contain; }
  .q-list { margin-top: 10px; }
  .q-row { font-size: 18px; line-height: 2.15; }
  .blank { display: inline-block; min-width: 2.0in; border-bottom: 2px solid #444; height: 0.95em; }
  .info-box { border: 2px solid #444; border-radius: 12px; padding: 9px 14px; margin: 9px 0; font-size: 15px; line-height: 1.5; }
  .img-missing { border: 3px dashed #cc3333; color: #cc3333; border-radius: 12px; padding: 50px 20px; text-align: center; font-size: 16px; margin: 20px auto; width: 70%; }
  .foot { position: absolute; bottom: 0.28in; left: 0.6in; right: 0.6in; }
  .footer { text-align: center; color: #999; font-size: 11px; }
  .page.cover { padding: 0; }
  .cover-img { width: 8.5in; height: 11in; object-fit: cover; object-position: center top; display: block; background: #fdf3e3; }
</style>
</head>
<body>${pagesHtml}</body>
</html>`;

return [{ json: { title: data.title, description: data.description, tags: data.tags, html: html } }];

const title = ($('4. Build HTML').first().json.title || 'worksheet');
const safe = title
  .replace(/[^a-zA-Z0-9 _-]/g, '')
  .trim()
  .replace(/\s+/g, '_')
  .slice(0, 70) || 'worksheet';
const fileName = safe + '.pdf';

// pull the binary straight from the PDFShift node to be safe
const pdfItem = $('5. HTML to PDF (PDFShift)').first();
const bin = (items[0].binary && items[0].binary.data) || (pdfItem.binary && pdfItem.binary.data);

const out = { json: { ...$json, pdf_file_name: fileName }, binary: {} };
if (bin) {
  out.binary.data = { ...bin, fileName: fileName, fileExtension: 'pdf', mimeType: 'application/pdf' };
}
return [out];

// ---- 1) Re-attach the PDF binary (HTTP nodes dropped it) ----
const renameItem = $('Rename File').first();
const fname = (renameItem.json && renameItem.json.pdf_file_name) || 'worksheet.pdf';
const out = { json: { ...$json }, binary: {} };
if (renameItem.binary && renameItem.binary.data) {
  out.binary.data = { ...renameItem.binary.data, fileName: fname, fileExtension: 'pdf', mimeType: 'application/pdf' };
}

// ---- 2) Attach a preview image; ALWAYS create out.binary.cover so Gmail never fails ----
// (fallback chain: cover -> mascot -> ภาพหน้าไหนก็ได้ -> 1x1 placeholder)
let images = {};
try { images = $('Image QA').first().json.images || {}; } catch (e) {}
if (!Object.keys(images).length) { try { images = $('Collect Images').first().json.images || {}; } catch (e) {} }
let previewB64 = images.cover || images.mascot || '';
if (!previewB64) {
  const k = Object.keys(images).find(key => images[key]);
  previewB64 = k ? images[k] : '';
}
const coverName = fname.replace(/\.pdf$/i, '') + '_COVER.jpg';
if (previewB64) {
  out.binary.cover = await this.helpers.prepareBinaryData(Buffer.from(previewB64, 'base64'), coverName, 'image/jpeg');
} else {
  // last-resort tiny image so the email STILL SENDS with the PDF even if every image failed
  const onePx = '/9j/4AAQSkZJRgABAQEAYABgAAD/2wBDAP//////////////////////////////////////////////////////////////////////////////////////wgALCAABAAEBAREA/8QAFBABAAAAAAAAAAAAAAAAAAAAAP/aAAgBAQABPxA=';
  out.binary.cover = await this.helpers.prepareBinaryData(Buffer.from(onePx, 'base64'), coverName, 'image/jpeg');
}

// ---- 3) Grade level -> เด็กเล็ก/โต + TPT grade tags ----
let grade = '';
try { grade = $('2. Analysis Agent').first().json.output.grade_level || ''; } catch (e) {}
if (!grade) { try { grade = $('Daily Assignment').first().json.grade || ''; } catch (e) {} }
if (!grade) grade = 'ไม่ระบุ';

const nums = (grade.match(/\d+/g) || []).map(Number);
const maxGrade = nums.length ? Math.max(...nums) : 0;
const lower = grade.toLowerCase();
const hasEarly = lower.includes('prek') || lower.includes('pre-k') || lower.includes('kindergarten') || lower.startsWith('k');

let ageGroup;
if (maxGrade >= 3) ageGroup = 'เด็กโต (ป.3 ขึ้นไป)';
else if (maxGrade > 0 || hasEarly) ageGroup = 'เด็กเล็ก (อนุบาล - ป.2)';
else ageGroup = 'ทุกช่วงวัย';

const map = { 0: 'PreK', 1: '1st', 2: '2nd', 3: '3rd', 4: '4th', 5: '5th', 6: '6th' };
let tptGrades = grade;
if (hasEarly && nums.length) tptGrades = 'PreK, K, ' + nums.map(n => map[n] || (n + 'th')).join(', ');
else if (hasEarly) tptGrades = 'PreK, K';

const title = $('4. Build HTML').first().json.title || '';
const desc = $('4. Build HTML').first().json.description || '';
const tags = ($('4. Build HTML').first().json.tags || []).join(', ');

let artTheme = '';
try { artTheme = $('2. Analysis Agent').first().json.output.art_theme || ''; } catch (e) {}

out.json.age_group = ageGroup;
out.json.grade_level = grade;
out.json.tpt_grades = tptGrades;

// ---- read TPT category recommendations from Content Agent ----
let tptSubjects = [], tptTags = [];
try {
  const co = $('3. Content Creation Agent').last().json.output;
  tptSubjects = Array.isArray(co.tpt_subjects) ? co.tpt_subjects : [];
  tptTags = Array.isArray(co.tpt_tags) ? co.tpt_tags : [];
} catch (e) {}
const subjectsLine = tptSubjects.length ? tptSubjects.join(', ') : '(เลือกเองตามวิชา)';
const resourceLine = tptTags.length ? tptTags.join(', ') : 'Worksheets, Printables, Activities';

// ---- 3.5) เช็คภาพขาดจาก Image QA (หลัง retry ครบแล้ว) ----
let missingIds = [];
try { missingIds = $('Image QA').first().json.missing_ids || []; } catch (e) {}
const missingPages = missingIds.filter(id => String(id).startsWith('page_'));
out.json.missing_images = missingIds.length;
out.json.missing_pages = missingPages.length;
const warnBlock = missingIds.length
  ? '\n⚠️ คำเตือน: ภาพเจนไม่สำเร็จ ' + missingIds.length + ' รูป (' + missingIds.join(', ') + ')' +
    (missingPages.length ? ' — มีหน้ากิจกรรมภาพขาด ควรรันชุดนี้ใหม่ก่อนอัปโหลดขาย!' : ' — เฉพาะภาพประกอบ ไม่กระทบหน้ากิจกรรม') + '\n'
  : '';

// ---- 4) Build a ready-to-paste TPT listing block ----
out.json.tpt_kit =
`====== TPT UPLOAD KIT (คัดลอกวางในฟอร์ม TPT) ======
${warnBlock}

[TITLE]
${title}

[DESCRIPTION]
${desc}

[ART THEME]  ${artTheme}
[GRADE LEVELS]  ${tptGrades}
[SUBJECT AREA — เลือกใน TPT]  ${subjectsLine}
[RESOURCE TYPE / TAGS — เลือกใน TPT]  ${resourceLine}
[PRICE]  $4.50
[SEARCH KEYWORDS]  ${tags}

[FILE]  แนบไฟล์ PDF ในอีเมลนี้
[PREVIEW/COVER]  ใช้ไฟล์ *_COVER.jpg ในอีเมลนี้เป็นภาพปก

เหมาะสำหรับ: ${ageGroup}
===============================================`;

return [out];

const staticData = $getWorkflowStaticData('global');
const histObj = (staticData.historyBySubject && typeof staticData.historyBySubject === 'object') ? staticData.historyBySubject : {};
staticData.historyBySubject = histObj;

// วิชาปัจจุบัน (รอบอัตโนมัติมาจาก Daily Assignment / เส้นทาง chat จะไม่มี node นี้)
let subject = '';
try { subject = $('Daily Assignment').first().json.subject || ''; } catch (e) {}

let topic = '';
let theme = '';
try {
  const a = $('2. Analysis Agent').first().json.output;
  topic = a.topic || '';
  theme = a.art_theme || '';
} catch (e) {}
if (!topic) { try { topic = $('4. Build HTML').first().json.title || ''; } catch (e) {} }

const key = subject || 'chat';
const arr = Array.isArray(histObj[key]) ? histObj[key] : [];
const entry = (topic + (theme ? ' [' + theme + ']' : '')).trim();
if (entry && !arr.includes(entry)) {
  arr.push(entry);
}
histObj[key] = arr.slice(-40);

return [{ json: { subject: key, saved_entry: entry } }];
